INSERT INTO `ec_reviews` VALUES (1, 9, NULL, NULL, 41, 3.00, 'Ok good product. I have some issues in customizations. But its not correct to blame the developer. The product is good. Good luck for your business.', 'published', '2024-12-08 15:52:16', '2024-12-08 15:52:16', '[\"products\\/4-1.jpg\",\"products\\/37-2.jpg\",\"products\\/43-1.jpg\"]');
INSERT INTO `ec_reviews` VALUES (2, 8, NULL, NULL, 47, 3.00, 'Those guys now what they are doing, the release such a good product that it\'s a pleasure to work with ! Even when I was stuck on the project, I created a ticket and the next day it was replied by the team. GOOD JOB guys. I love working with them :)', 'published', '2024-12-08 15:52:16', '2024-12-08 15:52:16', '[\"products\\/20-3.jpg\",\"products\\/23-2.jpg\",\"products\\/38-3.jpg\"]');
INSERT INTO `ec_reviews` VALUES (3, 3, NULL, NULL, 18, 2.00, 'The code is good, in general, if you like it, can you give it 5 stars?', 'published', '2024-12-08 15:52:16', '2024-12-08 15:52:16', '[\"products\\/38-3.jpg\"]');
INSERT INTO `ec_reviews` VALUES (4, 1, NULL, NULL, 59, 1.00, 'I Love this Script. I also found how to add other fees. Now I just wait the BIG update for the Marketplace with the Bulk Import. Just do not forget to make it to be Multi-language for us the Botble Fans.', 'published', '2024-12-08 15:52:16', '2024-12-08 15:52:16', '[\"products\\/4.jpg\",\"products\\/5-2.jpg\",\"products\\/10-2.jpg\",\"products\\/43-1.jpg\"]');
INSERT INTO `ec_reviews` VALUES (5, 2, NULL, NULL, 15, 4.00, 'This web app is really good in design, code quality & features. Besides, the customer support provided by the Botble team was really fast & helpful. You guys are awesome!', 'published', '2024-12-08 15:52:16', '2024-12-08 15:52:16', '[\"products\\/12-1.jpg\",\"products\\/13-1.jpg\",\"products\\/24.jpg\",\"products\\/25-2.jpg\"]');
