INSERT INTO `pages` VALUES (21, 'Term and Conditions', '<div>[term-and-conditions title=\"Terms and Conditions\" subtitle=\"Amet nulla facilisi morbi tempus iaculis urna\" image=\"general/banner-term-and-conditions.png\" quantity=\"10\" title_1=\"Limitation of Liability\" description_1=\"Under no circumstances shall Archi Elite be liable for any direct, indirect, special, incidental or consequential damages, including, but not limited to, loss of data or profit, arising out of the use, or the inability to use, the materials on this site, even if Archi Elite or an authorized representative has been advised of the possibility of such damages. If your use of materials from this site results in the need for servicing, repair or correction of equipment or data, you assume any costs thereof.\" title_2=\"Licensing Policy\" description_2=\"Archi e WordPress plugins and themes are released under the GNU General Public License v2 or later. Please refer to licensing policy page for licensing details.\" title_3=\"Product Compatibility\" description_3=\"The products are developed to be compatible with the latest version of WordPress because we always strive to stay up-to-date with the latest version of WordPress. You might experience certain performance or functionality glitches with the products if you use any version prior to that.\" title_4=\"Delivery\" description_4=\"Your purchased product(s) information will be emailed to the email address (that you will provide) once we receive your payment. Even though this usually takes a few minutes, it may also take up to 24 hours. You can contact us through our contact page if you do not receive your email after waiting for this time period. You will also have access to your purchased products from your account in Archi Elite after logging in.\" title_5=\"Ownership\" description_5=\"All the products are the property of Archi Elite. So you may not claim ownership (intellectual or exclusive) over any of our products, modified or unmodified. Our products come ‘as is’, without any kind of warranty, either expressed or implied. Under no circumstances can our juridical person be accountable for any damages including, but not limited to, direct, indirect, special, incidental or consequential damages or other losses originating from the employment of or incapacity to use our products.\" title_6=\"Browser Compatibility\" description_6=\"We consider it our duty to offer a great experience across most major browsers, which is why our products support the latest modern web browsers including (but not limited to) Firefox, Safari, Chrome & Internet Explorer 9+. However, the performance may vary between different browsers, versions, and operating systems.\" title_7=\"Updates\" description_7=\"Our themes are constantly updated to be compatible with the latest stable version of WordPress. Please ensure that you always use the most current version of our themes.\" title_8=\"Theme Support\" description_8=\"Please refer to Help and Support Policy page for details.\" title_9=\"Price Changes\" description_9=\"Reserves the right to modify or suspend (temporarily or permanently) a subscription at any point of time and from time to time with or without any notice.\" title_10=\"Refund Policy\" description_10=\"Please refer to Refund Policy page for details.\"][/term-and-conditions]</div>', 1, NULL, 'full-width', NULL, 'published', '2024-12-08 15:52:00', '2024-12-08 15:52:00');
INSERT INTO `pages` VALUES (22, 'Cookie Policy', '<h3>EU Cookie Consent</h3><p>To use this website we are using Cookies and collecting some Data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>', 1, NULL, 'page-detail', NULL, 'published', '2024-12-08 15:52:00', '2024-12-08 15:52:00');
INSERT INTO `pages` VALUES (23, 'Privacy policy', '<h3>EU Privacy policy</h3><p>To use this website we are using Cookies and collecting some Data. To be compliant with the EU GDPR we give you to choose if you allow us to use certain Cookies and to collect some Data.</p><h4>Essential Data</h4><p>The Essential Data is needed to run the Site you are visiting technically. You can not deactivate them.</p><p>- Session Cookie: PHP uses a Cookie to identify user sessions. Without this Cookie the Website is not working.</p><p>- XSRF-Token Cookie: Laravel automatically generates a CSRF \"token\" for each active user session managed by the application. This token is used to verify that the authenticated user is the one actually making the requests to the application.</p>', 1, NULL, 'page-detail', NULL, 'published', '2024-12-08 15:52:00', '2024-12-08 15:52:00');
