  INDEX `ec_invoices_reference_type_reference_id_index`(`reference_type` ASC, `reference_id` ASC) USING BTREE,
  INDEX `ec_invoices_payment_id_index`(`payment_id` ASC) USING BTREE,
  INDEX `ec_invoices_status_index`(`status` ASC) USING BTREE
